package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.*;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Cleaner_clean_TriageGen0Test {

    private Cleaner cleaner;

    @Before
    public void setUp() {
        cleaner = new Cleaner(org.jsoup.safety.Whitelist.basic());
    }

    @Test
    public void testClean_NullDocument_ShouldThrowNullPointerException() {
        assertThrows(NullPointerException.class, () -> cleaner.clean(null));
    }

    @Test
    public void testClean_EmptyDocument_ShouldReturnCleanDocument() {
        Document dirtyDocument = Jsoup.parse("", "UTF-8");
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertEquals("", cleanDocument.html());
    }

    @Test
    public void testClean_ValidDocument_ShouldReturnCleanDocument() {
        Document dirtyDocument = Jsoup.parse("<html><body><p>Valid content</p></body></html>", "UTF-8");
        assertTrue(cleaner.isValid(dirtyDocument));
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertEquals("<p>Valid content</p>", cleanDocument.body().html());
    }

    @Test
    public void testClean_InvalidDocument_ShouldReturnCleanDocumentWithSafeNodes() {
        Document dirtyDocument = Jsoup.parse("<html><body><script>alert('XSS');</script><p>Valid content</p></body></html>", "UTF-8");
        assertFalse(cleaner.isValid(dirtyDocument));
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertEquals("<p>Valid content</p>", cleanDocument.body().html());
    }

    @Test
    public void testClean_MixedContentDocument_ShouldReturnCleanDocumentWithSafeNodes() {
        Document dirtyDocument = Jsoup.parse("<html><body><p>Valid content</p><script>alert('XSS');</script></body></html>", "UTF-8");
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertEquals("<p>Valid content</p>", cleanDocument.body().html());
    }

    @Test
    public void testClean_MalformedDocument_ShouldReturnCleanDocument() {
        Document dirtyDocument = Jsoup.parse("<html><body><p>Unclosed tag", "UTF-8");
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertEquals("<p>Unclosed tag</p>", cleanDocument.body().html());
    }
}
